// Parity with the legacy Go implementation (goldens generated by legacy-go `kb`).
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { describe, expect, it } from 'vitest';
import { detectedConfig } from '../src/config/config.js';
import { scan } from '../src/scan/scan.js';
import { symbolJSON } from '../src/model.js';
import { extractFacts } from '../src/facts/facts.js';
import { renderFacts } from '../src/facts/render.js';
import { simhash, similarity } from '../src/extract/hash.js';

const repo = path.resolve(__dirname, '..');
const golden = path.join(repo, 'test/golden/minishop');
const read = (f: string) => fs.readFileSync(path.join(golden, f), 'utf8');

describe('minishop parity with Go', () => {
  it('symbols: ids, hashes, signatures, refs', async () => {
    const cfg = detectedConfig(path.join(repo, 'examples/minishop'));
    const r = await scan(cfg, cfg.root);
    expect(r.graph.parse_failures).toEqual([]);
    expect(JSON.parse(JSON.stringify(r.graph.symbols.map(symbolJSON)))).toEqual(JSON.parse(read('symbols.json')));
  }, 60000);
  it('facts JSON byte-identical (routes/testids/apis)', async () => {
    const cfg = detectedConfig(path.join(repo, 'examples/minishop'));
    const r = await scan(cfg, cfg.root);
    const out = renderFacts(extractFacts(cfg, r), r.graph, cfg.platforms.map((p) => p.name));
    for (const f of ['routes.json', 'testids.json', 'apis.json']) expect(out.get('facts/' + f)).toBe(read(f));
  }, 60000);
  it('template compound + change sets: plans identical, verify PASS', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-parity-'));
    const root = path.join(tmp, 'minishop');
    fs.cpSync(path.join(repo, 'examples/minishop'), root, { recursive: true });
    const kb = (...args: string[]) => execFileSync('node', [path.join(repo, 'dist/cli.js'), '--root', root, ...args], { stdio: ['ignore', 'pipe', 'ignore'] }).toString();
    try {
      kb('init');
      kb('compound', '--llm', 'template');
      for (const ch of ['01-cart-limit', '02-arkts-api-rename', '03-profile-route']) {
        fs.cpSync(path.join(repo, 'examples/minishop-changes', ch, 'files'), root, { recursive: true });
        // v2 adds plan.tree (hierarchy); the v1 part must stay identical to Go
        const plan = JSON.parse(kb('plan', '--json', '--dry-run'));
        expect(plan.tree).toBeDefined();
        delete plan.tree;
        expect(JSON.stringify(plan, null, 2) + '\n').toBe(read(`plan-${ch}.json`).replace(/\\u003c/g, '<').replace(/\\u003e/g, '>').replace(/\\u0026/g, '&'));
        kb('compound', '--llm', 'template');
      }
      expect(JSON.parse(kb('verify', '--json')).ok).toBe(true);
    } finally {
      fs.rmSync(tmp, { recursive: true, force: true });
    }
  }, 120000);
});

describe('hash helpers', () => {
  it('simhash/similarity', () => {
    expect(simhash([])).toBe('0000000000000000');
    const a = simhash(['a', 'b', 'c', 'd']);
    expect(similarity(a, a)).toBe(1);
  });
});
